#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct BodyTermWrapper {
    pub node: Rc<Node>,
    pub shape: LoweredShape,
}

pub fn body_term_edge_named(e: Rc<Edge>, name: std::string::String) -> bool {
    match (*e.label.clone()).clone() {
    EdgeLabel::Authored { name: n, .. } => (n.clone() == name.clone()),
    EdgeLabel::StructuralLabel { label: _, .. } => false,
    EdgeLabel::Positional => false,
}
}

pub fn body_term_seal_shape(seal: Rc<BodyTermLoweredSeal>) -> LoweredShape {
    seal.shape()
}

pub fn body_term_wrapper_optional(n: Rc<Node>) -> Option<Rc<BodyTermWrapper>> {
    match (*n.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => if (crate::std_algebra::length(n.children.clone()) == 1) {
        match v1_rt::list_get_optional(&n.children.clone(), 0) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(e) => match (*e.label.clone()).clone() {
    EdgeLabel::StructuralLabel { label: ref __rc_label, .. } => { match __rc_label.as_ref() {
    StructuralEdgeLabel::CoreMarker { marker: marker, .. } => match (*marker.clone()).clone() {
    CoreEdgeLabel::BodyTermLoweredEdge { seal: seal, .. } => crate::std_optional::optional_present(Rc::new(BodyTermWrapper {
    node: e.target.clone(),
    shape: body_term_seal_shape(seal.clone()),
})),
    _ => crate::std_optional::optional_absent(),
},
    StructuralEdgeLabel::ProductionEdge { .. } => crate::std_optional::optional_absent(),
} },
    EdgeLabel::Authored { name: _, .. } => crate::std_optional::optional_absent(),
    EdgeLabel::Positional => crate::std_optional::optional_absent(),
},
}
    } else {
        crate::std_optional::optional_absent()
    },
    Connective::Atom { identity: _, .. } => crate::std_optional::optional_absent(),
    Connective::Disj => crate::std_optional::optional_absent(),
    Connective::Arrow => crate::std_optional::optional_absent(),
    Connective::Instantiation => crate::std_optional::optional_absent(),
} },
    NodeKind::ComputationNode { behavior: _, .. } => crate::std_optional::optional_absent(),
}
}

pub fn body_term_seal(node: Rc<Node>, shape: LoweredShape) -> Rc<Node> {
    if body_lower_has_grammar_projection_edge(node.clone()) {
        node.clone()
    } else {
        match body_term_wrapper_optional(node.clone()) {
    Some(_) => node.clone(),
    std::option::Option::None => crate::v2_std_node::node_lowered_from(Rc::new(NodeKind::TypeNode {
    connective: Rc::new(Connective::Conj),
}), Rc::new(vec![crate::v2_std_node::core_edge(Rc::new(CoreEdgeLabel::BodyTermLoweredEdge {
    seal: crate::v2_std_node::body_term_lowered_seal(shape),
}), node.clone())]), node.clone()),
}
    }
}

pub fn body_term_sealed_outcome(o: Rc<Outcome<Rc<Node>>>, shape: LoweredShape) -> Rc<Outcome<Rc<Node>>> {
    match (*o.clone()).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: n, diagnostics: ref __rc_diagnostics, .. } => { let d = __rc_diagnostics.as_ref(); Rc::new(Outcome::Accepted {
    value: body_term_seal(n.clone(), shape),
    diagnostics: Box::new(d.clone()),
}) },
}
}

pub fn body_term_sealed_lowering(o: Rc<Outcome<Rc<BodyLowering>>>, shape: LoweredShape) -> Rc<Outcome<Rc<BodyLowering>>> {
    match (*o.clone()).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: ref __rc_value, diagnostics: ref __rc_diagnostics, .. } if matches!(__rc_value.as_ref(), BodyLowering::BodyLowered { node: _, .. }) => { let BodyLowering::BodyLowered { node: n, .. } = __rc_value.as_ref() else { unreachable!() }; let d = __rc_diagnostics.as_ref(); Rc::new(Outcome::Accepted {
    value: Rc::new(BodyLowering::BodyLowered {
    node: body_term_seal(n.clone(), shape),
}),
    diagnostics: Box::new(d.clone()),
}) },
    Outcome::Accepted { value: retained, diagnostics: ref __rc_diagnostics, .. } => { let d = __rc_diagnostics.as_ref(); Rc::new(Outcome::Accepted {
    value: retained.clone(),
    diagnostics: Box::new(d.clone()),
}) },
}
}

pub fn body_term_literal_token_payload_field(id: std::string::String) -> Option<std::string::String> {
    if (id.clone() == "dag_token_int_literal".to_string()) {
        crate::std_optional::optional_present("integer_literal_magnitude_field".to_string())
    } else {
        if (id.clone() == "dag_token_string_literal".to_string()) {
            crate::std_optional::optional_present("string_literal_value_field".to_string())
        } else {
            if (id.clone() == "dag_token_float_literal".to_string()) {
                crate::std_optional::optional_present("float_literal_lexeme_field".to_string())
            } else {
                crate::std_optional::optional_absent()
            }
        }
    }
}

pub fn body_term_is_leaf(n: Rc<Node>) -> bool {
    match (*n.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Atom { identity: id, .. } => if (crate::std_algebra::length(n.children.clone()) == 0) {
        true
    } else {
        if (crate::std_algebra::length(n.children.clone()) == 1) {
            match body_term_literal_token_payload_field(id.clone()) {
    std::option::Option::None => false,
    Some(field) => match v1_rt::list_get_optional(&n.children.clone(), 0) {
    Some(e) => body_term_edge_named(e.clone(), field.clone()),
    std::option::Option::None => false,
},
}
        } else {
            false
        }
    },
    Connective::Conj => (crate::std_algebra::length(n.children.clone()) == 0),
    Connective::Disj => false,
    Connective::Arrow => false,
    Connective::Instantiation => false,
} },
    NodeKind::ComputationNode { behavior: _, .. } => false,
}
}

pub fn body_term_of(node: Rc<Node>) -> Rc<Outcome<Rc<BodyTerm>>> {
    match body_term_wrapper_optional(node.clone()) {
    Some(w) => crate::v2_std_diagnostic::outcome_accepted(Rc::new(BodyTerm::Lowered {
    node: w.node.clone(),
    shape: w.shape.clone(),
})),
    std::option::Option::None => if body_lower_has_grammar_projection_edge(node.clone()) {
        crate::v2_std_diagnostic::outcome_accepted(Rc::new(BodyTerm::RawParse {
    node: node.clone(),
}))
    } else {
        if body_term_is_leaf(node.clone()) {
            crate::v2_std_diagnostic::outcome_accepted(Rc::new(BodyTerm::RawLeaf {
    node: node.clone(),
}))
        } else {
            Rc::new(Outcome::Rejected {
    diagnostics: body_term_unrecognised_diagnostics(node.clone()),
})
        }
    },
}
}

pub fn body_term_unrecognised_diagnostics(node: Rc<Node>) -> Rc<NonEmptyDiagnostics> {
    crate::v2_std_diagnostic::diagnostics_singleton(body_lower_diagnostic("body_lowering_reason_unrecognised_lowered_shape".to_string(), node))
}

