pub fn body_lower_reduce_emitted_non_leaf(folded: Rc<Node>, emitted: std::string::String) -> Rc<Outcome<Rc<Node>>> {
    if body_lower_is_metadata_preserved_emitted(emitted.clone()) {
        crate::v2_std_diagnostic::outcome_accepted(folded.clone())
    } else {
        if (emitted.clone() == "dag_surface_binary_expr".to_string()) {
            match (*body_lower_try_infix_transform(folded.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: Some(transform), .. } => crate::v2_std_diagnostic::outcome_accepted(body_term_seal(transform.clone(), LoweredShape::LoweredOperatorExpression)),
    Outcome::Accepted { value: std::option::Option::None, .. } => body_lower_reduce_passthrough(folded.clone()),
}
        } else {
            if (emitted.clone() == "dag_surface_postfix_expr".to_string()) {
                body_lower_reduce_or_keep(body_term_sealed_outcome(body_lower_postfix_expr(folded.clone()), LoweredShape::LoweredPostfix), folded.clone())
            } else {
                if (emitted.clone() == "dag_surface_primary_expr".to_string()) {
                    body_lower_reduce_or_keep(body_term_sealed_outcome(body_lower_primary_expr(folded.clone()), LoweredShape::LoweredPrimary), folded.clone())
                } else {
                    if crate::v2_std_compilers_sugar::sugar_is_pass_through_emitted(emitted.clone()) {
                        body_lower_reduce_passthrough(folded.clone())
                    } else {
                        if (emitted.clone() == "dag_surface_fn_decl".to_string()) {
                            body_lower_reduce_or_keep(body_term_sealed_outcome(body_lowering_refuse_retained(body_lower_fn_decl_to_arrow(folded.clone())), LoweredShape::LoweredFnDeclaration), folded.clone())
                        } else {
                            if (emitted.clone() == "dag_surface_test_fn_decl".to_string()) {
                                body_lower_reduce_or_keep(body_term_sealed_outcome(body_lowering_refuse_retained(body_lower_test_fn_decl_to_member(folded.clone())), LoweredShape::LoweredTestDeclaration), folded.clone())
                            } else {
                                if (emitted.clone() == "dag_surface_data_decl".to_string()) {
                                    body_lower_reduce_or_keep(body_term_sealed_outcome(body_lowering_refuse_retained(body_lower_data_decl_to_member(folded.clone())), LoweredShape::LoweredDataDeclaration), folded.clone())
                                } else {
                                    crate::v2_std_diagnostic::outcome_accepted(folded.clone())
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn body_lower_reduce(folded: Rc<Node>) -> Rc<Outcome<Rc<Node>>> {
    match (*body_term_of(folded.clone())).clone() {
    Outcome::Accepted { value: ref __rc_value, .. } => { match __rc_value.as_ref() {
    BodyTerm::Lowered { .. } => crate::v2_std_diagnostic::outcome_accepted(folded.clone()),
    _ => if crate::v2_extdeps_languages_dag::dag_resolve_preserve_module_metadata_subtree(folded.clone()) {
        crate::v2_std_diagnostic::outcome_accepted(folded.clone())
    } else {
        match crate::v2_std_grammar::parse_production_emitted_identity_optional(folded.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_accepted(folded.clone()),
    Some(emitted) => body_lower_reduce_emitted(folded.clone(), emitted.clone()),
}
    },
} },
    Outcome::Rejected { diagnostics: r, .. } => if crate::v2_extdeps_languages_dag::dag_resolve_preserve_module_metadata_subtree(folded.clone()) {
        crate::v2_std_diagnostic::outcome_accepted(folded.clone())
    } else {
        Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
})
    },
}
}

