#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct ControlFormFound {
    pub emitted: Symbol,
    pub captured: Rc<Node>,
}

pub fn body_lower_is_control_form_emitted(id: std::string::String) -> bool {
    ((((id.clone() == "dag_surface_if_expr".to_string()) || (id.clone() == "dag_surface_match_expr".to_string())) || (id.clone() == "dag_surface_loop_expr".to_string())) || (id.clone() == "dag_surface_let_expr".to_string()))
}

pub fn body_lower_node_is_delimiter_atom(n: Rc<Node>, opening: bool) -> bool {
    match crate::v2_std_grammar::node_atom_identity_optional(crate::v2_std_compilers_sugar::sugar_deep_unwrap_optional(n)) {
    Some(id) => if opening.clone() {
        ((id.clone() == "dag_token_lparen".to_string()) || (id.clone() == "dag_token_lbrace".to_string()))
    } else {
        ((id.clone() == "dag_token_rparen".to_string()) || (id.clone() == "dag_token_rbrace".to_string()))
    },
    std::option::Option::None => false,
}
}

pub fn body_lower_find_control_form_optional(mut __tco_loop_root: Rc<Node>) -> Option<Rc<ControlFormFound>> {
    { loop {
        #[allow(unused_mut)]
        let mut root = __tco_loop_root;
        match crate::v2_std_grammar::parse_production_emitted_identity_optional(root.clone()) {
    Some(id) => { match crate::v2_extdeps_languages_dag::parse_production_captured_child_optional(root.clone()) {
    std::option::Option::None => { break crate::std_optional::optional_absent(); },
    Some(captured) => { if body_lower_is_control_form_emitted(id.clone()) {
            break crate::std_optional::optional_present(Rc::new(ControlFormFound {
    emitted: id.clone(),
    captured: captured.clone(),
}));
} else {
            if body_lower_find_captured_prunable(id.clone()) {
                break crate::std_optional::optional_absent();
} else {
                {
                    let __tco_0 = captured.clone();
__tco_loop_root = __tco_0;
continue;
}
}
} },
} },
    std::option::Option::None => { match crate::v2_std_compilers_sugar::sugar_sequence_pair_optional(root.clone()) {
    std::option::Option::None => { break crate::std_optional::optional_absent(); },
    Some(pair) => { if crate::v2_std_node::is_empty_conj_root(crate::v2_std_compilers_sugar::sugar_deep_unwrap_optional(pair.right.clone())) {
            {
                let __tco_0 = pair.left.clone();
__tco_loop_root = __tco_0;
continue;
}
} else {
            if body_lower_node_is_delimiter_atom(pair.right.clone(), false) {
                {
                    let __tco_0 = pair.left.clone();
__tco_loop_root = __tco_0;
continue;
}
} else {
                if body_lower_node_is_delimiter_atom(pair.left.clone(), true) {
                    {
                        let __tco_0 = pair.right.clone();
__tco_loop_root = __tco_0;
continue;
}
} else {
                    break crate::std_optional::optional_absent();
}
}
} },
} },
}
} }
}

