pub fn body_lower_forward_row_apply(shell: Rc<Node>, emitted: std::string::String) -> Rc<Outcome<Rc<BodyLowering>>> {
    if (emitted.clone() == "dag_surface_fn_decl".to_string()) {
        body_term_sealed_lowering(body_lower_fn_decl_to_arrow(shell.clone()), LoweredShape::LoweredFnDeclaration)
    } else {
        if (emitted.clone() == "dag_surface_test_fn_decl".to_string()) {
            body_term_sealed_lowering(body_lower_test_fn_decl_to_member(shell.clone()), LoweredShape::LoweredTestDeclaration)
        } else {
            if (emitted.clone() == "dag_surface_data_decl".to_string()) {
                body_term_sealed_lowering(body_lower_data_decl_to_member(shell.clone()), LoweredShape::LoweredDataDeclaration)
            } else {
                if (emitted.clone() == "dag_surface_fn_body".to_string()) {
                    body_term_sealed_lowering(body_lower_fn_body_shell(shell.clone()), LoweredShape::LoweredFnBody)
                } else {
                    if (emitted.clone() == "dag_surface_match_expr".to_string()) {
                        body_term_sealed_lowering(body_lowering_lowered(body_lower_match_expr(shell.clone())), LoweredShape::LoweredMatch)
                    } else {
                        if (emitted.clone() == "dag_surface_if_expr".to_string()) {
                            body_term_sealed_lowering(body_lowering_lowered(body_lower_if_expr(shell.clone())), LoweredShape::LoweredBranch)
                        } else {
                            if (emitted.clone() == "dag_surface_loop_expr".to_string()) {
                                body_term_sealed_lowering(body_lowering_lowered(body_lower_loop_expr(shell.clone())), LoweredShape::LoweredLoop)
                            } else {
                                if (emitted.clone() == "dag_surface_let_expr".to_string()) {
                                    body_term_sealed_lowering(body_lowering_lowered(body_lower_let_expr(shell.clone())), LoweredShape::LoweredLet)
                                } else {
                                    body_lower_wrapper_retained_shell(shell.clone())
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

